package org.sleepwell.app;
import android.content.Context;import java.time.*;
/** Read-only admission against the saved source and its consumed-occurrence marker. */
final class NextAlarmOverrides {
 static String summary(Context context,Alarm alarm){if(alarm.nextOverrideInvalid)return "Review or undo override";if(alarm.nextOverride==null)return alarm.days.isEmpty()?"Recurring alarms only":"Ordinary schedule";try{ZoneId zone=ZoneId.systemDefault();current(context,alarm,zone);long target=alarm.nextOverride.at(zone);return target<=System.currentTimeMillis()?"Time passed · ordinary schedule resumes":(alarm.nextOverride.skipped(alarm,zone)?"Skipped · ":"")+alarm.nextOverride.targetDate+" · "+RecordUi.clock(context,target,zone);}catch(RuntimeException invalid){return "Review or undo override";}}
 static Alarm saved(Context context,Alarm draft){try(Store store=Records.open(context)){Alarm current=store.alarm(draft.id);if(current==null||!AlarmSkips.scheduleKey(current).equals(AlarmSkips.scheduleKey(draft))||!AlarmSkips.owner(current).equals(AlarmSkips.owner(draft)))throw new IllegalArgumentException("Save base-schedule changes first, then reopen Next alarm only.");return current;}}
 static long source(Context context,Alarm alarm,long now,ZoneId zone){if(!alarm.enabled||alarm.nap!=null||alarm.napInvalid||alarm.date!=null||alarm.dateInvalid||alarm.days.isEmpty()||alarm.repeatInvalid||alarm.nextOverrideInvalid)throw new IllegalArgumentException("Use an enabled saved recurring alarm. One-time alarms use Run on; naps use their timer.");if(alarm.nextOverride!=null)return alarm.nextOverride.sourceAt(alarm,zone);if(alarm.skip!=null||alarm.skipInvalid)throw new IllegalArgumentException("Undo the existing skipped occurrence before choosing a next-alarm override.");long chosen=AlarmSkips.next(context,alarm,now,zone);if(chosen<=now)throw new IllegalArgumentException("No future source occurrence is scheduled.");return CalendarAlarms.skipBase(context,alarm,chosen,now,zone);}
 static void current(Context context,Alarm alarm,ZoneId zone){if(alarm.nextOverrideInvalid)throw new IllegalArgumentException("Review or undo the next-alarm override.");if(alarm.nextOverride==null)return;alarm.nextOverride.check(alarm,zone);if(Prefs.of(context).getLong("lastOccurrence_"+alarm.id,0)!=alarm.nextOverride.last)throw new IllegalArgumentException("This source occurrence changed. Undo the old override and review a new one.");}
 static boolean eligible(Context context,Alarm alarm,ZoneId zone){try{current(context,alarm,zone);return true;}catch(RuntimeException invalid){return false;}}
 static void draft(Context context,Alarm alarm,Alarm original){if(alarm.nextOverride==null){if(alarm.nextOverrideInvalid)throw new IllegalArgumentException("Review or undo the next-alarm override.");return;}ZoneId zone=ZoneId.systemDefault();current(context,alarm,zone);NextAlarmOverride value=alarm.nextOverride;boolean changed=original.nextOverride==null||!value.key().equals(original.nextOverride.key());if(!changed)return;long now=System.currentTimeMillis();if(!value.reviewZone.equals(zone.getId())||value.at(zone)<=now)throw new IllegalArgumentException("The reviewed target passed or the time zone changed. Review Next alarm only again.");if(!alarm.enabled)throw new IllegalArgumentException("Enable and save the recurring alarm before choosing an override.");if(original.nextOverride==null){Alarm base=Alarm.read(alarm.json());base.setNextOverride(null);if(!AlarmSkips.baseScheduleKey(base).equals(AlarmSkips.baseScheduleKey(original)))throw new IllegalArgumentException("Save base-schedule changes before choosing an override.");if(value.sourceAt(alarm,zone)<=now||value.sourceAt(alarm,zone)!=source(context,base,now,zone))throw new IllegalArgumentException("The next source occurrence changed. Review it again.");}}
 private NextAlarmOverrides(){}
}
